<script>import {onMount} from 'svelte';import {getMe,updateMe,uploadPhoto,changePassword} from '../api/usersApi.js';import {authStore} from '../../auth/states/authStore.js';import {getErrorMessage} from '../../../helpers/toolsHelper.js';let profile=$state({name:'',email:''});let loading=$state(true);let busy=$state(false);let error=$state('');let notice=$state('');let currentPassword=$state('');let newPassword=$state('');onMount(async()=>{try{const r=await getMe();profile={...(r?.data?.user||r?.data||{}),name:(r?.data?.user||r?.data||{}).name||'',email:(r?.data?.user||r?.data||{}).email||''};authStore.setUser(profile)}catch(e){error=getErrorMessage(e)}finally{loading=false}});async function save(e){e.preventDefault();busy=true;error='';try{const r=await updateMe({name:profile.name,email:profile.email});profile={...profile,...(r?.data?.user||r?.data||{})};authStore.setUser(profile);notice='Profil berhasil diperbarui.'}catch(e){error=getErrorMessage(e)}finally{busy=false}}async function photo(e){const file=e.currentTarget.files?.[0];if(!file)return;try{await uploadPhoto(file);notice='Foto profil berhasil diunggah.'}catch(err){error=getErrorMessage(err)}}async function password(e){e.preventDefault();busy=true;error='';try{await changePassword(currentPassword,newPassword);currentPassword='';newPassword='';notice='Kata sandi berhasil diubah.'}catch(e){error=getErrorMessage(e)}finally{busy=false}}</script>
<svelte:head><title>Profil · Delcom Link Tree</title></svelte:head><p class="eyebrow">AKUN</p><h1>Profil saya</h1><p class="muted">Perbarui informasi dan keamanan akunmu.</p>{#if loading}<p role="status">Memuat profil…</p>{:else}<div class="profile-grid"><section class="panel"><h2>Informasi profil</h2><form class="form-stack" onsubmit={save}><label for="profile-name">Nama</label><input id="profile-name" bind:value={profile.name} required/><label for="profile-email">Email</label><input id="profile-email" type="email" bind:value={profile.email} required/><label for="profile-photo">Foto profil</label><input id="profile-photo" type="file" accept="image/*" onchange={photo}/><button class="btn btn-primary" disabled={busy}>Simpan profil</button></form></section><section class="panel"><h2>Ubah kata sandi</h2><form class="form-stack" onsubmit={password}><label for="current-password">Kata sandi saat ini</label><input id="current-password" type="password" bind:value={currentPassword} required autocomplete="current-password"/><label for="new-password">Kata sandi baru</label><input id="new-password" type="password" bind:value={newPassword} required minlength="8" autocomplete="new-password"/><button class="btn btn-primary" disabled={busy}>Ubah kata sandi</button></form></section></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="success" role="status">{notice}</p>{/if}{/if}
